namespace CareTogether.Domain;

public enum MemberRole { CareRecipient, Caregiver, Clinician, Admin }
public enum MedicationStatus { Active, Paused, Completed }
public enum MedicationScheduleType { Once, Daily, Weekly, Monthly }
public enum AppointmentStatus { Scheduled, Completed, Cancelled }
public enum HandoffStatus { Draft, Sent, Accepted, Declined, Cancelled }
public enum InvitationStatus { Pending, Accepted, Revoked }
public enum CareTaskStatus { Open, Assigned, InProgress, Done, Cancelled }

public abstract class Entity { public Guid Id { get; set; } = Guid.NewGuid(); public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; }
public sealed class User : Entity { public required string Email { get; set; } public required string PasswordHash { get; set; } public required string DisplayName { get; set; } public MemberRole Role { get; set; } public ICollection<CareTeamMember> Teams { get; set; } = []; }
public sealed class CareCircle : Entity { public required string Name { get; set; } public required string RecipientName { get; set; } public string? Notes { get; set; } public ICollection<CareTeamMember> Members { get; set; } = []; }
public sealed class CareTeamMember : Entity { public Guid CareCircleId { get; set; } public CareCircle CareCircle { get; set; } = null!; public Guid UserId { get; set; } public User User { get; set; } = null!; public MemberRole Role { get; set; } public bool IsActive { get; set; } = true; public DateTimeOffset? DeactivatedAt { get; set; } }
public sealed class CareInvitation : Entity { public Guid CareCircleId { get; set; } public required string Email { get; set; } public MemberRole Role { get; set; } public string? Message { get; set; } public required string Token { get; set; } public InvitationStatus Status { get; set; } = InvitationStatus.Pending; public Guid InvitedByUserId { get; set; } public DateTimeOffset ExpiresAt { get; set; } }
public sealed class CareTask : Entity { public Guid CareCircleId { get; set; } public Guid? AppointmentId { get; set; } public required string Title { get; set; } public string? Details { get; set; } public string? PreviousDetails { get; set; } public DateTimeOffset DueAt { get; set; } public Guid? AssignedToUserId { get; set; } public CareTaskStatus Status { get; set; } = CareTaskStatus.Open; public CareTaskStatus? PreviousStatus { get; set; } public bool IsCompleted { get; set; } }
public sealed class Medication : Entity { public Guid CareCircleId { get; set; } public required string Name { get; set; } public required string Dosage { get; set; } public required string Schedule { get; set; } public MedicationScheduleType ScheduleType { get; set; } = MedicationScheduleType.Daily; public DateTimeOffset? OnceAt { get; set; } public int? Occurrences { get; set; } public string? TimesOfDay { get; set; } public DateOnly? StartDate { get; set; } public DateOnly? EndDate { get; set; } public DayOfWeek? WeeklyDay { get; set; } public int? MonthlyDay { get; set; } public int ScheduleUtcOffsetMinutes { get; set; } public string? Instructions { get; set; } public MedicationStatus Status { get; set; } = MedicationStatus.Active; public MedicationStatus? PreviousStatus { get; set; } }
public sealed class MedicationOccurrence : Entity { public Guid MedicationId { get; set; } public DateTimeOffset ScheduledAt { get; set; } }
public sealed class MedicationLog : Entity { public Guid MedicationId { get; set; } public DateTimeOffset ScheduledAt { get; set; } public DateTimeOffset? TakenAt { get; set; } public bool Skipped { get; set; } public string? Note { get; set; } }
public sealed class Appointment : Entity { public Guid CareCircleId { get; set; } public required string Title { get; set; } public required string Provider { get; set; } public DateTimeOffset StartsAt { get; set; } public string? Location { get; set; } public string? Notes { get; set; } public string? PreviousNotes { get; set; } public AppointmentStatus Status { get; set; } = AppointmentStatus.Scheduled; public AppointmentStatus? PreviousStatus { get; set; } }
public sealed class Conversation : Entity { public Guid CareCircleId { get; set; } public required string Title { get; set; } public ICollection<Message> Messages { get; set; } = []; }
public sealed class Message : Entity { public Guid ConversationId { get; set; } public Guid SenderUserId { get; set; } public required string Body { get; set; } public DateTimeOffset? ReadAt { get; set; } }
public sealed class CareHandoff : Entity { public Guid CareCircleId { get; set; } public Guid FromUserId { get; set; } public Guid ToUserId { get; set; } public required string Summary { get; set; } public string? Risks { get; set; } public string? NextSteps { get; set; } public HandoffStatus Status { get; set; } = HandoffStatus.Draft; public DateTimeOffset? AcceptedAt { get; set; } public DateTimeOffset? DeclinedAt { get; set; } public DateTimeOffset? CancelledAt { get; set; } }
public sealed class UserNotification : Entity { public Guid UserId { get; set; } public required string Type { get; set; } public required string Title { get; set; } public required string Body { get; set; } public Guid? RelatedId { get; set; } public DateTimeOffset? ReadAt { get; set; } }
public sealed class JournalEntry : Entity { public Guid CareCircleId { get; set; } public Guid AuthorUserId { get; set; } public required string Body { get; set; } public string? Category { get; set; } }
public sealed class HealthReading : Entity { public Guid CareCircleId { get; set; } public required string Type { get; set; } public decimal Value { get; set; } public decimal? SecondaryValue { get; set; } public int? Pulse { get; set; } public DateTimeOffset RecordedAt { get; set; } }
public sealed class CareDocument : Entity { public Guid CareCircleId { get; set; } public Guid? TaskId { get; set; } public Guid? AppointmentId { get; set; } public Guid? MedicationId { get; set; } public required string Name { get; set; } public required string Category { get; set; } public string? Notes { get; set; } public string? ContentType { get; set; } public byte[]? FileContent { get; set; } }
public sealed class EmergencyContact : Entity { public Guid CareCircleId { get; set; } public required string Name { get; set; } public required string Relationship { get; set; } public required string Phone { get; set; } public bool IsPrimary { get; set; } }
public sealed class RefreshToken : Entity { public Guid UserId { get; set; } public required string TokenHash { get; set; } public DateTimeOffset ExpiresAt { get; set; } public DateTimeOffset? RevokedAt { get; set; } }
